import{af as t,z as a,J as d,ab as o}from"./chunks/framework.Cvdy85y1.js";const p=JSON.parse('{"title":"Structure","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"devices/api/protocol/structure.md","filePath":"devices/api/protocol/structure.md"}'),r={name:"devices/api/protocol/structure.md"};function i(s,e,l,h,n,c){return a(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793280522000"},[...e[0]||(e[0]=[o('<h1 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h1><ul><li>Protocol Version: The version of the protocol (always 3).</li><li>Message Length: The length of the message, including the version, header, data, and checksum.</li><li>Message Type: The type of message. This is used to determine how to interpret the message.</li><li>Data: Both data field (header and payload) are made up of the same format: <ul><li>Field Count: The number of fields in the data.</li><li>Fields: List of field types in the data</li><li>Data: The data itself, making used of bBytes to represent length and values.</li></ul></li><li>Checksum: A 16-bit CRC checksum of the message (XMODEM).</li></ul><h3 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h3><p>Within each Data element (the header data, or payload data), the structure is as follows:</p><table tabindex="0"><thead><tr><th>Byte position</th><th>Description</th><th>Type</th><th>Example</th></tr></thead><tbody><tr><td>1 -&gt; 2</td><td>Number of fields (n)</td><td>uint16</td><td>2 0</td></tr><tr><td>3 -&gt; 3+n</td><td>Field types</td><td>[]uint8</td><td>1 2</td></tr><tr><td>3+n+1 -&gt; end</td><td>Data</td><td>[]bBytes</td><td>[1 8] [3 9 9 9]</td></tr></tbody></table><p>The Data should be in the order of the field types.</p><p>The example data includes <code>2</code> data fields, the first of type <code>1</code>, with value byte array <code>[8]</code>, the second of type <code>2</code>, with value byte array <code>[9 9 9]</code>.</p><h4 id="bbytes" tabindex="-1">bBytes <a class="header-anchor" href="#bbytes" aria-label="Permalink to &quot;bBytes&quot;">​</a></h4><p>bBytes are a byte array that represents a length and then the data itself. The size of the length prefix depends on the field&#39;s data type ID:</p><ul><li>Data type IDs <strong>0–127</strong>: the length prefix is a <code>uint8</code> (1 byte), allowing up to 255 bytes of data.</li><li>Data type IDs <strong>128–255</strong>: the length prefix is a <code>uint16</code> little-endian value (2 bytes), allowing up to 65535 bytes of data, though on device messages are generally limited to 2000 bytes.</li></ul><p>The boundary is the field ID, and includes ID 128. Fields 128–255 always use a two-byte length, even when they contain fewer than 256 bytes. Decoders must use the field ID to choose the correct layout.</p><p>For example, for a field with data type ID <code>1</code> (&lt; 128), <code>[1 8]</code> would represent a byte array of length 1, with the value 8.</p><p>Or for a field with data type ID <code>3</code> (&lt; 128), <code>[3 9 9 9]</code> would represent a byte array of length 3, with the values 9, 9, 9.</p><p>For a field with data type ID <code>200</code> (&gt;= 128), the length prefix is 2 bytes little-endian, so <code>[3 0 9 9 9]</code> would represent a byte array of length 3, with the values 9, 9, 9.</p>',14)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
